class Label {
    public readonly string Name;
    public Label(bool first) { if (first) Name = "first"; else Name = "second"; }
}
class Holder {
    public Label Item = new Label(true);
    public string Name;
    public Holder(bool stop) {
        if (stop) { Name = "early"; return; }
        do { Name = "normal"; } while (false);
    }
}
void Main() {
    var h = new Holder(false); Print(h.Item.Name); Print(h.Name);
    Print(new Holder(true).Name); Print(new Label(false).Name);
}
